using System.Diagnostics;namespace VtuberBot.Core;public sealed record ProcessSpec(IReadOnlyList<string>Command,string?WorkingDirectory=null){public ProcessSpec(IEnumerable<string>c,string?cwd=null):this(c.ToArray(),cwd){if(Command.Count==0||string.IsNullOrWhiteSpace(Command[0]))throw new ArgumentException("Command must not be empty.");}}public sealed class ProcessManagerException:Exception{public ProcessManagerException(string m,Exception?e=null):base(m,e){}}public sealed class OwnedProcess:IDisposable{readonly object g=new();readonly ProcessSpec s;readonly ILogger l;Process?p;public OwnedProcess(ProcessSpec x,ILogger y){s=x;l=y;}public int?Pid{get{lock(g)return p?.Id;}}public bool IsRunning{get{lock(g)return p is{HasExited:false};}}public int Start(){lock(g){if(p is{HasExited:false})throw new ProcessManagerException("Process already running.");if(s.WorkingDirectory is not null&&!Directory.Exists(s.WorkingDirectory))throw new ProcessManagerException("Working directory does not exist.");var i=new ProcessStartInfo{FileName=s.Command[0],UseShellExecute=false,CreateNoWindow=true};if(s.WorkingDirectory is not null)i.WorkingDirectory=s.WorkingDirectory;for(int n=1;n<s.Command.Count;n++)i.ArgumentList.Add(s.Command[n]);var x=new Process{StartInfo=i};try{if(!x.Start())throw new ProcessManagerException("Process failed to start.");}catch(Exception e)when(e is System.ComponentModel.Win32Exception or InvalidOperationException){x.Dispose();throw new ProcessManagerException("Process failed to start.",e);}p=x;l.Info("Owned process started: pid={0}",x.Id);return x.Id;}}public int?Wait(TimeSpan?timeout=null){Process?x;lock(g)x=p;if(x is null)return null;if(timeout is null)x.WaitForExit();else if(!x.WaitForExit(timeout.Value))return null;return x.ExitCode;}public int?Stop(TimeSpan?timeout=null){Process?x;lock(g)x=p;if(x is null)return null;if(!x.HasExited){x.Kill(false);if(!x.WaitForExit(timeout??TimeSpan.FromSeconds(5))){x.Kill(false);x.WaitForExit();}}var code=x.ExitCode;lock(g)if(ReferenceEquals(p,x))p=null;x.Dispose();return code;}public int Restart(TimeSpan?timeout=null){Stop(timeout);return Start();}public void Dispose()=>Stop(TimeSpan.FromSeconds(2));}